public class MainActivity extends Activity {
 TextView report; DisplayManager dm; Presentation presentation; LinearLayout layout; int scans=0; volatile String poseReport="Not tested"; volatile boolean poseRunning=false; volatile boolean liveStop=false; volatile double[][] liveRotation=null; volatile String liveStatus="Not started"; volatile long liveStamp=0; volatile String imuReport="Not tested"; boolean imuRunning=false; volatile String networkReport="Not tested"; boolean networkRunning=false; volatile String hidReport="Not tested"; volatile boolean probing=false; UsbDevice pendingDevice; final String USB_ACTION="com.example.xrealprobe.USB_PERMISSION"; final BroadcastReceiver usbReceiver=new BroadcastReceiver(){public void onReceive(Context ctx,Intent intent){if(USB_ACTION.equals(intent.getAction())){UsbDevice d=pendingDevice;pendingDevice=null;if(d!=null && ((UsbManager)getSystemService(USB_SERVICE)).hasPermission(d))startRead(d);else {hidReport="USB permission denied";scan();}}}}; final Handler handler=new Handler(Looper.getMainLooper()); final Runnable refresh=new Runnable(){public void run(){scan();handler.postDelayed(this,2000);}};
 @Override public void onCreate(Bundle b){super.onCreate(b); dm=(DisplayManager)getSystemService(DISPLAY_SERVICE); layout=new LinearLayout(this);layout.setOrientation(1); ScrollView scroll=new ScrollView(this);scroll.addView(layout);scroll.setOnApplyWindowInsetsListener((v,insets)->{int pad=(int)(12*getResources().getDisplayMetrics().density);android.graphics.Insets safe=insets.getInsets(WindowInsets.Type.systemBars()|WindowInsets.Type.displayCutout());v.setPadding(safe.left+pad,safe.top+pad,safe.right+pad,safe.bottom+pad);return insets;}); if(android.os.Build.VERSION.SDK_INT<30){scroll.setOnApplyWindowInsetsListener(null);scroll.setFitsSystemWindows(true);scroll.setPadding(16,16,16,16);}setContentView(scroll);scroll.requestApplyInsets();button("Refresh USB / displays",()->{scan();Toast.makeText(this,"Refreshed #"+scans,Toast.LENGTH_SHORT).show();});button("Copy diagnostic report",()->{scan();((android.content.ClipboardManager)getSystemService(CLIPBOARD_SERVICE)).setPrimaryClip(ClipData.newPlainText("XREAL",report.getText()));Toast.makeText(this,"Fresh report copied",Toast.LENGTH_SHORT).show();});button("AUTO tracked cube + return (30 sec)",()->{if(poseRunning||imuRunning)return;showStereo(0);if(presentation!=null&&presentation.isShowing())startTrackedCube();});button("Start tracking on existing external display (60 sec)",()->startTrackedCube());button("Stop tracked cube",()->{liveStop=true;if(presentation!=null)presentation.dismiss();});button("Guided head tracking (28 sec)",()->probePose(false));button("Test live IMU via TCP",()->probeImu());button("Test XREAL local network",()->probeNetwork());button("Test live USB HID (10 sec)",()->probeUsb());button("Stereo test on external display",()->showStereo(0));button("Request external display mode",()->chooseMode());button("Stereo test on phone (preview)",()->{setContentView(new Stereo(this));});report=new TextView(this);report.setTextIsSelectable(true);layout.addView(report);if(Build.VERSION.SDK_INT>=33)registerReceiver(usbReceiver,new IntentFilter(USB_ACTION),Context.RECEIVER_NOT_EXPORTED);else registerReceiver(usbReceiver,new IntentFilter(USB_ACTION));scan();}
 void button(String s,Runnable r){Button b=new Button(this);b.setText(s);b.setOnClickListener(v->r.run());layout.addView(b);}
 void scan(){StringBuilder s=new StringBuilder("Refresh #"+(++scans)+" at "+new java.text.SimpleDateFormat("HH:mm:ss.SSS",Locale.US).format(new Date())+"\nUSB devices (descriptors only):\n");UsbManager u=(UsbManager)getSystemService(USB_SERVICE);for(UsbDevice d:u.getDeviceList().values()){s.append(String.format(Locale.US,"VID=%04x PID=%04x interfaces=%d\n",d.getVendorId(),d.getProductId(),d.getInterfaceCount()));for(int i=0;i<d.getInterfaceCount();i++){UsbInterface f=d.getInterface(i);s.append("  interface "+f.getId()+" class="+f.getInterfaceClass()+" subclass="+f.getInterfaceSubclass()+" endpoints="+f.getEndpointCount()+"\n");}}s.append("\nDisplays:\n");for(Display d:dm.getDisplays()){Display.Mode m=d.getMode();s.append(d.getDisplayId()+" "+d.getName()+" "+m.getPhysicalWidth()+"x"+m.getPhysicalHeight()+" @"+m.getRefreshRate()+" mode="+m.getModeId()+"\n");for(Display.Mode mode:d.getSupportedModes())s.append("  supported mode "+mode.getModeId()+": "+mode.getPhysicalWidth()+"x"+mode.getPhysicalHeight()+" @"+mode.getRefreshRate()+"\n");}s.append("\nLive HID test:\n").append(hidReport);s.append("\nXREAL network test:\n").append(networkReport);s.append("\nIMU TCP test:\n").append(imuReport);s.append("\nDecoded head angles (experimental):\n").append(poseReport);s.append("\nLive cube: ").append(liveStatus);report.setText(s);}
 static double dot(double[] a,double[] b){double v=0;for(int i=0;i<a.length;i++)v+=a[i]*b[i];return v;}
 static double[] unit(double[] a){double n=Math.sqrt(dot(a,a));if(n>1e-12)for(int i=0;i<a.length;i++)a[i]/=n;return a;}
 static double[] cross(double[] a,double[] b){return new double[]{a[1]*b[2]-a[2]*b[1],a[2]*b[0]-a[0]*b[2],a[0]*b[1]-a[1]*b[0]};}
 static double[] qmul(double[] a,double[] b){return new double[]{a[0]*b[0]-a[1]*b[1]-a[2]*b[2]-a[3]*b[3],a[0]*b[1]+a[1]*b[0]+a[2]*b[3]-a[3]*b[2],a[0]*b[2]-a[1]*b[3]+a[2]*b[0]+a[3]*b[1],a[0]*b[3]+a[1]*b[2]-a[2]*b[1]+a[3]*b[0]};}
 void probePose(boolean live){if(poseRunning||imuRunning)return;poseRunning=true;poseReport="Connecting. Keep head still until first beep.";scan();new Thread(()->{String result="";try{android.net.ConnectivityManager cm=(android.net.ConnectivityManager)getSystemService(CONNECTIVITY_SERVICE);android.net.Network chosen=null;for(android.net.Network n:cm.getAllNetworks()){android.net.LinkProperties lp=cm.getLinkProperties(n);if(lp==null)continue;for(android.net.LinkAddress a:lp.getLinkAddresses())if("169.254.2.10".equals(a.getAddress().getHostAddress()))chosen=n;}if(chosen==null)throw new java.io.IOException("XREAL network missing");try(java.net.Socket sock=chosen.getSocketFactory().createSocket()){sock.connect(new java.net.InetSocketAddress("169.254.2.1",52998),3000);sock.setSoTimeout(1000);java.io.InputStream in=new java.io.BufferedInputStream(sock.getInputStream());byte[] frame=new byte[134];int used=0,count=0,mag=0,bad=0,cal=0;double[] bias=new double[3],gravity=new double[3],angles=new double[3],min=new double[3],max=new double[3];double[] q={1,0,0,0};double[][] basis=null;int phase=-1;double[][] phaseMin=new double[4][3],phaseMax=new double[4][3];android.media.ToneGenerator tones=new android.media.ToneGenerator(android.media.AudioManager.STREAM_MUSIC,70);long start=SystemClock.elapsedRealtime(),prev=0,update=0;StringBuilder log=new StringBuilder();int imuId=-1;try{while(SystemClock.elapsedRealtime()-start<(live?34000:28000)&&!isFinishing()&&(!live||!liveStop)){int b;try{b=in.read();}catch(java.net.SocketTimeoutException e){continue;}if(b<0)break;if(used==0&&b!=0x28&&b!=0x27)continue;if(used==1&&b!=0x36){used=0;if(b==0x28||b==0x27)frame[used++]=(byte)b;continue;}frame[used++]=(byte)b;if(used==6&&(frame[2]!=0||frame[3]!=0||frame[4]!=0||(frame[5]&255)!=128)){used=0;bad++;continue;}if(used<134)continue;used=0;java.nio.ByteBuffer p=java.nio.ByteBuffer.wrap(frame).order(java.nio.ByteOrder.LITTLE_ENDIAN);int type=p.getInt(30);if(type==4){mag++;continue;}if(type!=11){bad++;continue;}int id=frame[74]&255;if(imuId<0)imuId=id;if(id!=imuId)continue;double[] g={p.getFloat(34),p.getFloat(38),p.getFloat(42)};double[] a={p.getFloat(46),p.getFloat(50),p.getFloat(54)};if(!Double.isFinite(g[0]+g[1]+g[2]+a[0]+a[1]+a[2])){bad++;continue;}long stamp=p.getLong(14);double dt=(stamp-prev)*1e-9;prev=stamp;count++;long elapsed=SystemClock.elapsedRealtime()-start;int next=elapsed<4000?0:live?1:elapsed<12000?1:elapsed<20000?2:3;if(next!=phase){phase=next;tones.startTone(android.media.ToneGenerator.TONE_PROP_BEEP,200);log.append("PHASE ").append(phase).append(" ").append(phase==0?"STILL":phase==1?"TURN LEFT RIGHT":phase==2?"LOOK UP DOWN":"TILT TO SHOULDERS").append("\n");}
if(phase==0){for(int i=0;i<3;i++){bias[i]+=g[i];gravity[i]+=a[i];}cal++;}else if(cal>0&&dt>0&&dt<0.05){if(basis==null){double[] up=unit(new double[]{-gravity[0],-gravity[1],-gravity[2]});double[] right=unit(new double[]{1-up[0]*up[0],-up[0]*up[1],-up[0]*up[2]});basis=new double[][]{right,up,cross(right,up)};log.append(String.format(Locale.US,"Gravity basis up %.3f %.3f %.3f%n",up[0],up[1],up[2]));}double[] w={g[0]-bias[0]/cal,g[1]-bias[1]/cal,g[2]-bias[2]/cal};double speed=Math.sqrt(dot(w,w));if(speed>1e-9){double half=speed*dt/2,scale=Math.sin(half)/speed;q=qmul(q,new double[]{Math.cos(half),w[0]*scale,w[1]*scale,w[2]*scale});q=unit(q);}if(live){double[] inv={q[0],-q[1],-q[2],-q[3]};double[][] mat=new double[3][3];for(int j=0;j<3;j++){double[] v=qmul(qmul(inv,new double[]{0,basis[j][0],basis[j][1],basis[j][2]}),q);double[] vec={v[1],v[2],v[3]};for(int i=0;i<3;i++)mat[i][j]=dot(basis[i],vec);}liveRotation=mat;liveStamp=SystemClock.elapsedRealtime();liveStatus="Tracking; samples "+count;}double sign=q[0]<0?-1:1;double vn=Math.sqrt(q[1]*q[1]+q[2]*q[2]+q[3]*q[3]);double factor=vn>1e-9?Math.toDegrees(2*Math.atan2(vn,Math.abs(q[0])))/vn:0;double[] rv={sign*q[1]*factor,sign*q[2]*factor,sign*q[3]*factor};for(int i=0;i<3;i++){angles[i]=dot(rv,basis[i]);min[i]=Math.min(min[i],angles[i]);max[i]=Math.max(max[i],angles[i]);phaseMin[phase][i]=Math.min(phaseMin[phase][i],angles[i]);phaseMax[phase][i]=Math.max(phaseMax[phase][i],angles[i]);}}if(elapsed-update>=1000){update=elapsed;String row=String.format(Locale.US,"%ds X %.1f Y %.1f Z %.1f | gyro %.3f %.3f %.3f | accel %.2f %.2f %.2f%n",elapsed/1000,angles[0],angles[1],angles[2],g[0],g[1],g[2],a[0],a[1],a[2]);log.append(row);poseReport=(phase==0?"CALIBRATING - keep still":phase==1?"TURN LEFT RIGHT":phase==2?"LOOK UP DOWN":"TILT TO SHOULDERS")+"\n"+row+"\n"+log;}}}finally{tones.startTone(android.media.ToneGenerator.TONE_PROP_ACK,200);try{Thread.sleep(220);}catch(InterruptedException ignored){}tones.release();}for(int ph=1;ph<=3;ph++)log.append(String.format(Locale.US,"Phase %d spans X %.1f Y %.1f Z %.1f%n",ph,phaseMax[ph][0]-phaseMin[ph][0],phaseMax[ph][1]-phaseMin[ph][1],phaseMax[ph][2]-phaseMin[ph][2]));result=String.format(Locale.US,"IMU frames=%d MAG=%d invalid=%d calibration=%d sensor=%d%nAxis X range %.1f to %.1f%nAxis Y range %.1f to %.1f%nAxis Z range %.1f to %.1f%n",count,mag,bad,cal,imuId,min[0],max[0],min[1],max[1],min[2],max[2])+log;}}catch(Exception e){result=e.toString();}poseReport=result;if(live)liveStatus="Finished: "+result.split("\n")[0];poseRunning=false;runOnUiThread(()->{if(live&&presentation!=null){presentation.dismiss();presentation=null;}if(!isFinishing())scan();});}).start();}
 void probeImu(){if(imuRunning||poseRunning)return;imuRunning=true;imuReport="Connecting; keep still for 5 seconds, then gently rotate head for 5 seconds";scan();new Thread(()->{StringBuilder out=new StringBuilder();try{android.net.ConnectivityManager cm=(android.net.ConnectivityManager)getSystemService(CONNECTIVITY_SERVICE);android.net.Network chosen=null;for(android.net.Network n:cm.getAllNetworks()){android.net.LinkProperties lp=cm.getLinkProperties(n);if(lp==null)continue;for(android.net.LinkAddress a:lp.getLinkAddresses())if("169.254.2.10".equals(a.getAddress().getHostAddress()))chosen=n;}if(chosen==null)throw new java.io.IOException("No Android network with address 169.254.2.10");try(java.net.Socket sock=chosen.getSocketFactory().createSocket()){sock.connect(new java.net.InetSocketAddress("169.254.2.1",52998),3000);sock.setSoTimeout(500);out.append("TCP connected from ").append(sock.getLocalAddress().getHostAddress()).append("\n");imuReport=out+"Reading for 10 seconds: first still, then rotate gently";java.io.InputStream input=sock.getInputStream();byte[] buf=new byte[4096];long start=SystemClock.elapsedRealtime();long[] bytes=new long[2];int[] reads=new int[2];String[] first={"",""},last={"",""};while(SystemClock.elapsedRealtime()-start<10000&&!isFinishing()){try{int got=input.read(buf);if(got<0){out.append("Remote closed stream\n");break;}if(got==0)continue;int phase=SystemClock.elapsedRealtime()-start<5000?0:1;bytes[phase]+=got;reads[phase]++;StringBuilder hex=new StringBuilder();for(int k=0;k<Math.min(got,96);k++)hex.append(String.format(Locale.US,"%02x",buf[k]&255));last[phase]=hex.toString();if(reads[phase]==1)first[phase]=last[phase];}catch(java.net.SocketTimeoutException ignored){}}for(int i=0;i<2;i++)out.append(i==0?"Still":"Moving").append(": bytes=").append(bytes[i]).append(" TCP reads=").append(reads[i]).append("\nfirst=").append(first[i]).append("\nlast=").append(last[i]).append("\n");}}catch(Exception e){out.append(e.toString());}imuReport=out.toString();runOnUiThread(()->{imuRunning=false;if(!isFinishing())scan();});}).start();}
 void probeNetwork(){if(networkRunning)return;networkRunning=true;networkReport="Testing local link...";scan();new Thread(()->{StringBuilder s=new StringBuilder();try{java.net.InetAddress target=java.net.InetAddress.getByName("169.254.2.1");java.util.Enumeration<java.net.NetworkInterface> interfaces=java.net.NetworkInterface.getNetworkInterfaces();while(interfaces!=null&&interfaces.hasMoreElements()){java.net.NetworkInterface n=interfaces.nextElement();if(n.isLoopback()||!n.isUp())continue;s.append(n.getName()).append(": ");for(java.net.InterfaceAddress a:n.getInterfaceAddresses()){if(a.getAddress() instanceof java.net.Inet4Address && a.getAddress().isLinkLocalAddress())s.append(a.getAddress().getHostAddress()).append("/").append(a.getNetworkPrefixLength()).append(" ");}s.append("\n");}android.net.ConnectivityManager cm=(android.net.ConnectivityManager)getSystemService(CONNECTIVITY_SERVICE);for(android.net.Network n:cm.getAllNetworks()){android.net.LinkProperties lp=cm.getLinkProperties(n);if(lp==null)continue;boolean local=false;for(android.net.LinkAddress la:lp.getLinkAddresses())if(la.getAddress() instanceof java.net.Inet4Address && la.getAddress().isLinkLocalAddress())local=true;if(!local)continue;s.append("Android link-local network: ").append(lp.getInterfaceName()).append("\n");try(java.net.Socket socket=n.getSocketFactory().createSocket()){socket.connect(new java.net.InetSocketAddress(target,80),1500);s.append("TCP 80 connected\n");}catch(Exception e){s.append("TCP 80: ").append(e.getClass().getSimpleName()).append(": ").append(e.getMessage()).append("\n");}}try{s.append("Default reachability: ").append(target.isReachable(1500)).append("\n");}catch(Exception e){s.append(e.toString());}}catch(Exception e){s.append(e.toString());}networkReport=s.toString();runOnUiThread(()->{networkRunning=false;if(!isFinishing())scan();});}).start();}
 void probeUsb(){if(probing||pendingDevice!=null)return;UsbManager u=(UsbManager)getSystemService(USB_SERVICE);for(UsbDevice d:u.getDeviceList().values())if(d.getVendorId()==0x3318 && d.getProductId()==0x0444){if(u.hasPermission(d))startRead(d);else {pendingDevice=d;hidReport="Waiting for USB permission";Intent i=new Intent(USB_ACTION).setPackage(getPackageName());u.requestPermission(d,PendingIntent.getBroadcast(this,0,i,PendingIntent.FLAG_IMMUTABLE));}scan();return;}hidReport="XREAL not found";scan();}
 void startRead(UsbDevice d){probing=true;hidReport="Reading; gently rotate head during test";new Thread(()->{StringBuilder out=new StringBuilder();UsbManager u=(UsbManager)getSystemService(USB_SERVICE);UsbDeviceConnection conn=null;try{conn=u.openDevice(d);if(conn==null){out.append("openDevice failed");return;}for(int n=0;n<d.getInterfaceCount();n++){UsbInterface f=d.getInterface(n);if(f.getInterfaceClass()!=UsbConstants.USB_CLASS_HID)continue;out.append("interface ").append(f.getId()).append(": ");if(!conn.claimInterface(f,false)){out.append("claim failed (no forced detach)\n");continue;}try{for(int k=0;k<f.getEndpointCount();k++){UsbEndpoint ep=f.getEndpoint(k);if(ep.getDirection()!=UsbConstants.USB_DIR_IN||ep.getType()!=UsbConstants.USB_ENDPOINT_XFER_INT)continue;int count=0,changed=0;byte[] prev=null,buf=new byte[Math.max(1,Math.min(4096,ep.getMaxPacketSize()))];String first="",last="";long end=SystemClock.elapsedRealtime()+5000;while(SystemClock.elapsedRealtime()<end&&!isFinishing()){int got=conn.bulkTransfer(ep,buf,buf.length,200);if(got>0){byte[] data=Arrays.copyOf(buf,got);StringBuilder h=new StringBuilder();for(int b=0;b<Math.min(got,64);b++)h.append(String.format(Locale.US,"%02x",data[b]&255));last=h.toString();if(count==0)first=last;if(prev!=null&&!Arrays.equals(prev,data))changed++;prev=data;count++;}}out.append(" endpoint ").append(ep.getAddress()).append(" packets=").append(count).append(" changed=").append(changed).append(" first=").append(first).append(" last=").append(last).append("\n");}}finally{conn.releaseInterface(f);}}}catch(Exception e){out.append(e.toString());}finally{if(conn!=null)conn.close();hidReport=out.toString();probing=false;runOnUiThread(()->{if(!isFinishing())scan();});}}).start();}
 void startTrackedCube(){if(poseRunning||imuRunning)return;if(presentation==null||!presentation.isShowing()){Toast.makeText(this,"First press Stereo test on external display",Toast.LENGTH_LONG).show();return;}liveStop=false;liveRotation=null;liveStamp=0;liveStatus="Calibrating - keep head still";probePose(true);}
 void chooseMode(){Display[] ds=dm.getDisplays(DisplayManager.DISPLAY_CATEGORY_PRESENTATION);if(ds.length==0){Toast.makeText(this,"No external display",Toast.LENGTH_SHORT).show();return;}Display.Mode[] modes=ds[0].getSupportedModes();String[] labels=new String[modes.length];for(int i=0;i<modes.length;i++){Display.Mode m=modes[i];labels[i]=m.getPhysicalWidth()+"x"+m.getPhysicalHeight()+" @"+m.getRefreshRate()+" (mode "+m.getModeId()+")";}new AlertDialog.Builder(this).setTitle("Request display mode (not guaranteed)").setItems(labels,(dialog,i)->showStereo(modes[i].getModeId())).show();}
 void showStereo(int modeId){Display[] ds=dm.getDisplays(DisplayManager.DISPLAY_CATEGORY_PRESENTATION);if(ds.length==0){Toast.makeText(this,"No external presentation display; try desktop mode",Toast.LENGTH_LONG).show();return;}if(presentation!=null)presentation.dismiss();liveStop=true;presentation=new Presentation(this,ds[0]);presentation.setContentView(new Stereo(presentation.getContext()));presentation.show();if(modeId!=0 && presentation.getWindow()!=null){WindowManager.LayoutParams a=presentation.getWindow().getAttributes();a.preferredDisplayModeId=modeId;presentation.getWindow().setAttributes(a);}new Handler(Looper.getMainLooper()).postDelayed(()->{if(!isFinishing())scan();},1500);}
 @Override protected void onResume(){super.onResume();handler.removeCallbacks(refresh);handler.post(refresh);}
 @Override protected void onPause(){handler.removeCallbacks(refresh);super.onPause();}
 @Override protected void onDestroy(){unregisterReceiver(usbReceiver);handler.removeCallbacks(refresh);if(presentation!=null)presentation.dismiss();super.onDestroy();}
 class Stereo extends View {Paint p=new Paint(3);long t=SystemClock.uptimeMillis();Stereo(Context c){super(c);}void line(Canvas c,float x,float y,float a,float b,int color,float w){p.setColor(color);p.setStrokeWidth(w);c.drawLine(x,y,a,b,p);} @Override protected void onDraw(Canvas c){c.drawColor(Color.BLACK);float w=getWidth()/2f,h=getHeight();double[][] m=liveRotation;boolean tracking=m!=null&&poseRunning&&!liveStop&&SystemClock.elapsedRealtime()-liveStamp<500;double ang=tracking?0:(SystemClock.uptimeMillis()-t)*.0007;for(int eye=0;eye<2;eye++){c.save();c.clipRect(eye*w,0,(eye+1)*w,h);float cx=(eye+.5f)*w,cy=h*.5f;float scale=Math.min(w,h)*.43f;float fx=(float)(w/(2*Math.tan(Math.toRadians(25.3))));float fy=(float)(h/(2*Math.tan(Math.toRadians(14.9))));float[][] pts=new float[8][2];boolean[] visible=new boolean[8];for(int i=0;i<8;i++){double x=((i&1)==0?-1:1)*.48,y=((i&2)==0?-1:1)*.48,z=((i&4)==0?-1:1)*.48;double rx=x*Math.cos(ang)+z*Math.sin(ang),rz=-x*Math.sin(ang)+z*Math.cos(ang)+3;if(tracking){double[] v={rx,-y,-rz};rx=dot(m[0],v);y=-dot(m[1],v);rz=-dot(m[2],v);}double e=eye==0?-.032:.032;visible[i]=rz>.1;if(visible[i]){pts[i][0]=cx+(float)((tracking?fx:scale)*((rx-e)/rz+e/3.0));pts[i][1]=cy+(float)((tracking?fy:scale)*y/rz);}}for(int i=0;i<8;i++)for(int j=0;j<3;j++){int k=i^(1<<j);if(k>i&&visible[i]&&visible[k])line(c,pts[i][0],pts[i][1],pts[k][0],pts[k][1],Color.CYAN,4);}p.setColor(Color.WHITE);p.setTextSize(h*.035f);c.drawText(tracking?"TRACKING - gray cross follows head":poseRunning&&!liveStop?"CALIBRATING - KEEP STILL":eye==0?"LEFT":"RIGHT",eye*w+20,h*.12f,p);line(c,cx-15,cy,cx+15,cy,Color.GRAY,2);line(c,cx,cy-15,cx,cy+15,Color.GRAY,2);c.restore();}postInvalidateDelayed(16);}}
}